"3.8\" fill=\"#F59E0B\"/\u003e\r\n          \u003cpath d=\"M26,46 Q38,56 50,46\" fill=\"none\" stroke=\"#F59E0B\" stroke-width=\"3\" stroke-linecap=\"round\"/\u003e\r\n        \u003c/svg\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv style=\"position:absolute;left:268px;top:56px;font-family:var(--font-mono);font-size:13px;font-weight:700;color:#F59E0B;\"\u003eANALOGÍA · LA MÁSCARA AMABLE\u003c/div\u003e\r\n      \u003cdiv style=\"position:absolute;left:268px;top:96px;width:830px;font-family:var(--font-head);font-size:32px;font-weight:700;color:#F8FAFC;line-height:1.25;\"\u003e\r\n        La alineación funciona como ponerle una \u003cspan style=\"color:#F59E0B;\"\u003emáscara educada\u003c/span\u003e a un sistema complejo.\r\n      \u003c/div\u003e\r\n      \u003cdiv style=\"position:absolute;left:268px;top:220px;width:830px;font-size:19px;color:#CBD5E1;line-height:1.45;\"\u003e\r\n        Mejora el tono y la seguridad superficial, \u003cstrong style=\"color:#F8FAFC;\"\u003epero no elimina por completo\u003c/strong\u003e los sesgos profundos ni las alucinaciones aprendidas en internet.\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv style=\"position:absolute;left:57.6px;top:678px;width:1164px;font-family:var(--font-body);font-size:12.5px;color:#64748B;\"\u003e\r\n      \u003cstrong style=\"font-family:var(--font-mono);color:#F59E0B;\"\u003eREFERENCIA:\u003c/strong\u003e Chen \u0026amp; Liu (2024) · Huyen (2025)\r\n    \u003c/div\u003e\r\n  \u003c/div\u003e\r\n\u003c/section\u003e\r\n",
